// ============================================================
// INTERVIEW AGENT: Format Response (v4.0 - Enhanced)
// Добавлено: валидация телефона, Амина, подтверждение данных
// ============================================================

const context = $('Execute Workflow Trigger').first().json;
const response = $json;

let parsed = {
  message: 'Расскажите немного о себе. Как вас зовут? 🤝',
  extracted_data: {},
  interview_complete: false,
  awaiting_confirmation: false,
  needs_escalation: false
};

try {
  const rawOutput = response.text || response.output || response.content || '';
  const cleanJson = String(rawOutput)
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = { ...parsed, ...JSON.parse(jsonMatch[0]) };
  }
} catch (e) {
  console.log('Interview parse error:', e.message);
}

// Мержим известные данные с новыми
const mergedData = { ...context.known_data };
if (parsed.extracted_data) {
  Object.keys(parsed.extracted_data).forEach(key => {
    const value = parsed.extracted_data[key];
    if (value && value !== 'unknown' && value !== null && value !== 'null' && value !== '') {
      mergedData[key] = value;
    }
  });
}

// ============================================================
// ВАЛИДАЦИЯ ТЕЛЕФОНА
// ============================================================
if (mergedData.phone) {
  let phone = String(mergedData.phone).replace(/[\s\-\(\)]/g, '');
  // Приводим к формату +7XXXXXXXXXX
  if (phone.startsWith('8') && phone.length === 11) {
    phone = '+7' + phone.substring(1);
  } else if (phone.startsWith('7') && phone.length === 11) {
    phone = '+' + phone;
  } else if (!phone.startsWith('+')) {
    phone = '+' + phone;
  }

  // Проверяем формат
  const phoneRegex = /^\+7\d{10}$/;
  if (!phoneRegex.test(phone)) {
    // Телефон невалидный, просим уточнить
    mergedData.phone = null;
    if (!parsed.message.includes('телефон')) {
      parsed.message += '\n\n📱 Пожалуйста, уточните ваш телефон в формате +7XXXXXXXXXX';
    }
  } else {
    mergedData.phone = phone;
  }
}

// ============================================================
// ПРОВЕРКА ПОЛНОТЫ ДАННЫХ
// ============================================================
const hasDocuments = mergedData.documents_status === 'yes' || mergedData.has_amina_app === true;
const requiredFields = ['first_name', 'citizenship', 'age', 'phone'];
const filledRequired = requiredFields.filter(f => 
  mergedData[f] && mergedData[f] !== null && mergedData[f] !== 'unknown'
);

const allDataCollected = filledRequired.length >= 4 && hasDocuments;

// ============================================================
// ЛОГИКА ПОДТВЕРЖДЕНИЯ
// ============================================================
let isComplete = false;
let awaitingConfirmation = parsed.awaiting_confirmation || false;

// Если все данные собраны и ожидаем подтверждения
if (allDataCollected && !parsed.interview_complete) {
  // Проверяем, подтвердил ли кандидат
  const userMsg = (context.user_message || '').toLowerCase();
  const confirmWords = ['да', 'верно', 'правильно', 'подтверждаю', 'все верно', 'всё верно', 'yes', 'ok', 'ок'];
  const isConfirmed = confirmWords.some(w => userMsg.includes(w));

  if (isConfirmed && context.known_data && Object.keys(context.known_data).length >= 4) {
    // Кандидат подтвердил данные
    isComplete = true;
    awaitingConfirmation = false;
  } else if (!awaitingConfirmation) {
    // Показываем сводку для подтверждения
    awaitingConfirmation = true;
  }
}

if (parsed.interview_complete) {
  isComplete = true;
}

return {
  // Context passthrough
  user_id: context.user_id,
  chat_id: context.chat_id,
  session_id: context.session_id,
  user_message: context.user_message,
  language: context.language,
  route_category: context.route_category,
  vacancies: context.vacancies,

  // Response
  response_message: parsed.message,
  final_message: parsed.message,
  extracted_data: mergedData,
  interview_complete: isComplete,
  awaiting_confirmation: awaitingConfirmation,
  show_language_buttons: false,
  needs_escalation: parsed.needs_escalation || false,

  // Debug info
  filled_required: filledRequired.length,
  has_documents: hasDocuments,
  all_data_collected: allDataCollected
};

// ============================================================
// INTERVIEW AGENT: LLM Error Fallback (v4.0)
// Если LLM недоступен, просим повторить позже
// ============================================================

const context = $('Execute Workflow Trigger').first().json;

console.log('⚠️ Interview Agent LLM error, using fallback');

const fallbackMessage = 'Извините, произошла техническая ошибка. 🔧\n\n' +
  'Пожалуйста, повторите ваше сообщение через несколько секунд.';

return {
  user_id: context.user_id,
  chat_id: context.chat_id,
  session_id: context.session_id,
  user_message: context.user_message,
  language: context.language,
  route_category: context.route_category,
  vacancies: context.vacancies,

  response_message: fallbackMessage,
  final_message: fallbackMessage,
  extracted_data: context.known_data || {},
  interview_complete: false,
  awaiting_confirmation: false,
  show_language_buttons: false,
  needs_escalation: false
};
